using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Reflection;using System.Collections.Generic;using System.Threading;using System.Web.Script.Serialization;using DualSteam;
public static class StabilityTests {
 static int passed;static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);passed++;}
 public static int Main(string[] args){string folder=Path.Combine(Engine.Home,"Verification","Stability-"+Guid.NewGuid().ToString("N"));try{if(args.Length==0){Directory.CreateDirectory(folder);Directory.CreateDirectory(Path.Combine(folder,"Tools"));File.Copy(typeof(Engine).Assembly.Location,Path.Combine(folder,"Dual Steam.exe"));File.Copy(Path.Combine(Engine.Home,@"Tools\NativeAccountControl.exe"),Path.Combine(folder,@"Tools\NativeAccountControl.exe"));string worker=Path.Combine(folder,"StabilityTests.exe"),csc=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),@"Microsoft.NET\Framework64\v4.0.30319\csc.exe");Engine.Run(csc,"/nologo /target:exe /r:System.Core.dll /r:System.Web.Extensions.dll /reference:"+Engine.Quote(typeof(Engine).Assembly.Location)+" /out:"+Engine.Quote(worker)+" "+Engine.Quote(Path.Combine(Engine.Home,@"Tests\StabilityTests.cs")));Console.WriteLine(Engine.Run(worker,"worker"));return 0;}
 Check(new JavaScriptSerializer().Deserialize<Preferences>("{\"ImportMillennium\":false}").RecoverMillennium,"existing preferences receive safe startup recovery by default");
 var helper=Assembly.LoadFrom(Path.Combine(Engine.Home,@"Tools\NativeAccountControl.exe")).GetType("NativeAccountControl").GetMethod("IsLauncher",BindingFlags.Static|BindingFlags.NonPublic);foreach(string name in new[]{"steam","STEAMWEBHELPER","steamservice","NativeAccountControl"})Check((bool)helper.Invoke(null,new object[]{name}),name+" excluded from game shutdown targets");Check(!(bool)helper.Invoke(null,new object[]{"Game-Win64-Shipping"}),"ordinary game remains eligible for owned-game checks");
 Engine.Current=new Settings{MainSteam=""};Check(!MillenniumSharing.Detected,"missing Steam path leaves optional add-ons unavailable without crashing");Check(PerformanceSnapshot.Main().Root==0,"missing Steam path returns an empty performance snapshot");
 string main=Path.Combine(Engine.Home,"Main"),root=Path.Combine(Engine.Home,"Second"),client=Path.Combine(root,"Client");Directory.CreateDirectory(Path.Combine(main,@"millennium\lib"));Directory.CreateDirectory(Path.Combine(main,@"millennium\config"));Directory.CreateDirectory(Path.Combine(client,@"millennium\config"));File.WriteAllText(Path.Combine(main,"wsock32.dll"),"fixture-loader");File.WriteAllText(Path.Combine(main,@"millennium\lib\millennium.dll"),"fixture-runtime");File.WriteAllText(Path.Combine(main,@"millennium\config\config.json"),"{\"general\":{\"accentColor\":\"blue\",\"checkForMillenniumUpdates\":true,\"checkForPluginAndThemeUpdates\":true,\"onMillenniumUpdate\":2},\"network\":{\"proxy\":\"main-private-secret\"}}");File.WriteAllText(Path.Combine(client,@"millennium\config\config.json"),"{\"network\":{\"proxy\":\"second-private-proxy\"}}");
 Engine.Current=new Settings{MainSteam=Path.Combine(main,"steam.exe"),NativeRoot=root,SecondSteam=Path.Combine(client,"steam.exe")};Preferences.Current=new Preferences{ImportMillennium=true,ImportThemeSettings=true,SyncMillennium=true};var plan=MillenniumSharing.Plan();var json=new JavaScriptSerializer();string configuration=System.Text.Encoding.UTF8.GetString(plan[@"millennium\config\config.json"]);var config=json.Deserialize<Dictionary<string,object>>(configuration);var general=(Dictionary<string,object>)config["general"];Check(Convert.ToString(general["accentColor"])=="blue","visual Millennium settings imported");Check(!Convert.ToBoolean(general["checkForMillenniumUpdates"])&&!Convert.ToBoolean(general["checkForPluginAndThemeUpdates"])&&!general.ContainsKey("onMillenniumUpdate"),"second runtime cannot inherit automatic update/restart preferences");Check(!configuration.Contains("main-private-secret")&&configuration.Contains("second-private-proxy"),"main proxy credentials excluded and second proxy preserved");MillenniumSharing.Import();Check(MillenniumSharing.CanDisable,"imported runtime has an owned recovery record");string loader=Path.Combine(client,"wsock32.dll");File.WriteAllText(loader,"changed");bool refused=false;try{MillenniumSharing.Disable();}catch(IOException){refused=true;}Check(refused&&File.ReadAllText(loader)=="changed","changed runtime is not silently removed");File.WriteAllBytes(loader,plan["wsock32.dll"]);MillenniumSharing.Disable();Check(!File.Exists(loader)&&!Preferences.Current.SyncMillennium&&!Preferences.Current.ImportMillennium,"disabling runtime also prevents automatic re-import");Check(File.ReadAllText(Path.Combine(main,"wsock32.dll"))=="fixture-loader","main runtime remains unchanged");
 Preferences.Current.ImportMillennium=true;File.WriteAllText(loader,"before-import");string marker=Path.Combine(Engine.Home,@"Data\millennium-import.json");File.WriteAllText(marker,"previous-marker");bool rolledBack=false;using(var held=new FileStream(marker,FileMode.Open,FileAccess.Read,FileShare.Read)){try{MillenniumSharing.Import();}catch(IOException){rolledBack=true;}}Check(rolledBack&&File.ReadAllText(loader)=="before-import"&&File.ReadAllText(marker)=="previous-marker","late marker failure rolls back runtime and preserves previous recovery record");Check(!Directory.GetFiles(client,"*.import-new",SearchOption.AllDirectories).Any(),"failed add-on import cleans temporary files");
 var release=new ReleaseInfo{Download="https://github.com/w-rakeeb/dual-steam/releases/download/v0.0.1/Dual-Steam-Windows.zip",Sha256=new string('0',64),Size=100};using(var cancel=new CancellationTokenSource()){cancel.Cancel();bool canceled=false;try{UpdateService.Download(release,null,cancel.Token);}catch(OperationCanceledException){canceled=true;}Check(canceled&&!Directory.GetFiles(Path.Combine(Engine.Home,"Updates"),"*.zip",SearchOption.AllDirectories).Any(),"canceled update makes no network request or partial ZIP");}bool invalid=false;release.Sha256="bad";try{UpdateService.Download(release);}catch(IOException){invalid=true;}Check(invalid,"invalid update metadata rejected before download");Console.WriteLine(passed+" stability checks passed.");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{if(args.Length==0&&Directory.Exists(folder))RemovalCore.DeleteTree(folder);}}
}